import java.awt.*;
import java.net.*;
import java.util.*;
import java.util.List;
import javax.swing.*;

final class RepeaterSessions {
    static final class Tab {String name,group="Default",url,request;int selected=-1;final List<Integer> history=new ArrayList<>();Tab(String name,String url,String request){this.name=name;this.url=url;this.request=request;}public String toString(){return group+" / "+name;}}
    final VulnApp app;final DefaultComboBoxModel<Tab> model=new DefaultComboBoxModel<>();final JComboBox<Tab> tabs=new JComboBox<>(model);final JComboBox<Integer> history=new JComboBox<>();boolean switching;Tab current;
    RepeaterSessions(VulnApp app){this.app=app;JPanel wrapper=new JPanel(new BorderLayout());Component original=app.tools.getComponentAt(3);wrapper.add(original);JPanel bar=VulnApp.bar(new JLabel("Requests"),tabs,VulnApp.button("New",this::create),VulnApp.button("Rename / group",this::rename),VulnApp.button("Duplicate",this::duplicate),VulnApp.button("Close",this::close),new JLabel("History"),history);wrapper.add(bar,BorderLayout.NORTH);app.tools.setComponentAt(3,wrapper);tabs.setPrototypeDisplayValue(new Tab("Request 000","",""));tabs.addActionListener(e->select());history.addActionListener(e->restoreHistory());create();}
    void snapshot(){if(current!=null){current.url=app.repeaterUrl.getText();current.request=app.repeaterRequest.getText();}}
    void create(){snapshot();if(model.getSize()>=50){app.log("Maximum 50 Repeater requests");return;}Tab tab=new Tab("Request "+(model.getSize()+1),app.repeaterUrl.getText(),app.repeaterRequest.getText());model.addElement(tab);tabs.setSelectedItem(tab);select();}
    void incoming(String url,String request){create();current.url=url;current.request=request;show();}
    void duplicate(){create();}
    void rename(){if(current==null)return;JTextField name=new JTextField(current.name),group=new JTextField(current.group);if(JOptionPane.showConfirmDialog(app,new Object[]{"Name",name,"Group",group},"Request details",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){current.name=name.getText();current.group=group.getText();tabs.repaint();}}
    void close(){if(model.getSize()<=1)return;model.removeElement(current);select();}
    void select(){if(switching)return;snapshot();current=(Tab)tabs.getSelectedItem();show();}
    void show(){if(current==null)return;switching=true;try{app.repeaterUrl.setText(current.url);app.repeaterRequest.setText(current.request);history.removeAllItems();current.history.forEach(history::addItem);if(current.selected>=0&&current.selected<app.entries.size()){var e=app.entries.get(current.selected);app.repeaterResponse.setText(new String(e.response(),VulnApp.WIRE));history.setSelectedItem(current.selected);}else app.repeaterResponse.setText("");}finally{switching=false;}}
    void restoreHistory(){if(switching||current==null)return;Integer index=(Integer)history.getSelectedItem();if(index==null||index<0||index>=app.entries.size())return;var e=app.entries.get(index);current.selected=index;current.url=e.url();current.request=new String(e.request(),VulnApp.WIRE);show();}
    void send(){snapshot();Tab target=current;String request=target.request,url=target.url;app.send.setEnabled(false);app.repeaterResponse.setText("Sending…");app.workers.submit(()->{try{var packet=VulnApp.parse(request.getBytes(VulnApp.WIRE));URI uri=packet.uri(url);long start=System.nanoTime();var reply=VulnApp.perform(packet,uri);long ms=(System.nanoTime()-start)/1000000;SwingUtilities.invokeLater(()->{app.addExchange(packet,uri,reply,ms,"Repeater");target.selected=app.entries.size()-1;target.history.add(target.selected);if(target.history.size()>100)target.history.removeFirst();if(current==target){show();app.repeaterView.received(ms,reply.bodySize());}});}catch(Exception ex){app.error(ex);SwingUtilities.invokeLater(()->{if(current==target)app.repeaterResponse.setText("Request failed: "+ex.getMessage());});}finally{SwingUtilities.invokeLater(()->app.send.setEnabled(true));}});}
    String state(){snapshot();List<Object> out=new ArrayList<>();for(int i=0;i<model.getSize();i++){Tab t=model.getElementAt(i);out.add(Map.of("name",t.name,"group",t.group,"url",t.url,"request",t.request,"selected",t.selected,"history",t.history));}return Json.write(Map.of("tabs",out,"active",tabs.getSelectedIndex()));}
    void restore(String saved){Map<String,Object> data=Json.object(Json.parse(saved));Object raw=data.get("tabs");if(!(raw instanceof List<?> list)||list.isEmpty()||list.size()>50)throw new IllegalArgumentException("Invalid Repeater tabs");switching=true;try{model.removeAllElements();for(Object item:list){Map<String,Object> row=Json.object(item);Tab tab=new Tab(row.get("name").toString(),row.get("url").toString(),row.get("request").toString());tab.group=row.get("group").toString();tab.selected=((Number)row.get("selected")).intValue();for(Object id:(List<?>)row.get("history"))tab.history.add(((Number)id).intValue());model.addElement(tab);}tabs.setSelectedIndex(Math.max(0,Math.min(model.getSize()-1,((Number)data.get("active")).intValue())));current=(Tab)tabs.getSelectedItem();}finally{switching=false;}show();}
}
